message.content:
{
  "definition_simple": "電車が通るための道。",
  "definition_standard": "鉄道の車両を走行させるために敷設された、レールと枕木からなる構造物。",
  "pos": "名詞",
  "semantic_class": "concrete",
  "sentences": [
    {
      "sentence": "線路の上を電車が走っている。",
      "tier": "T1"
    },
    {
      "sentence": "踏切で線路を渡るときは注意が必要です。",
      "tier": "T1"
    },
    {
      "sentence": "工事のため、この線路は一時的に使えません。",
      "tier": "T2"
    },
    {
      "sentence": "線路沿いに咲く桜がとてもきれいだ。",
      "tier": "T2"
    },
    {
      "sentence": "新しい線路を敷く計画が進んでいる。",
      "tier": "T3"
    },
    {
      "sentence": "線路の保守点検は毎日行われている。",
      "tier": "T3"
    },
    {
      "sentence": "その駅の線路は複雑に絡み合っている。",
      "tier": "T4"
    },
    {
      "sentence": "線路の幅を変えることで、高速走行に対応できる。",
      "tier": "T4"
    },
    {
      "sentence": "線路の老朽化が原因で、ダイヤが大幅に乱れた。",
      "tier": "T5"
    },
    {
      "sentence": "線路の電気設備を最新のシステムに更新する工事が始まった。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": null,
  "primary_collocate": "敷く",
  "collocation_distractors": [
    {
      "word": "道路",
      "reason": "道路は車が通るためのもので、線路は電車用の異なる交通路であり、直接的な連語関係にはない。"
    },
    {
      "word": "駅",
      "reason": "駅は線路の一部ではあるが、線路そのものと固定的に結びつく連語ではなく、関係性が薄い。"
    },
    {
      "word": "電車",
      "reason": "電車は線路の上を走るが、'線路を電車が走る'という文構造であって、'線路'と'電車'が固定連語を形成するわけではない。"
    }
  ],
  "collocation_wrong_collocate": "閉じる",
  "collocation_wrong_collocate_reason": "「線路を閉じる」という表現は通常使われず、正しくは「線路を封鎖する」「線路を閉鎖する」などが適切。",
  "cloze_distractors": [
    {
      "sentence_for_cloze": "新しい___を敷く計画が進んでいる。",
      "blank_word": "線路",
      "distractors": [
        {
          "word": "道路",
          "reason": "道路は車道であり、電車の線路とは意味が異なる。"
        },
        {
          "word": "鉄道",
          "reason": "鉄道はシステム全体を指し、具体的なレールの敷設には「線路」が適切。"
        },
        {
          "word": "駅",
          "reason": "駅は施設であり、敷くという動作の対象として不自然。"
        }
      ]
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼は線路を歩いている。",
      "reason": "「線路を歩く」は危険行為を表す実用的な文ではあるが、「歩く」は線路の正しい使用法（走行）ではなく、語用論的に不適切なコロケーション（歩行対象としての線路は通常想定されない）。"
    },
    {
      "sentence": "線路が新しい電車を走らせた。",
      "reason": "「線路」は無生物であり、「走らせる」の主語になるのは不自然。正しくは「電車が線路を走る」または「線路を電車が走る」。"
    },
    {
      "sentence": "私は線路に乗った。",
      "reason": "「線路に乗る」は誤った用法。通常「電車に乗る」と言い、「線路に乗る」は物理的に線路の上に乗るという意味にはなるが、交通手段として使われない。"
    }
  ],
  "spot_incorrect": {
    "sentence": "彼は線路を降りた。",
    "error_description": "「降りる」は乗り物（電車・バスなど）から降りる場合に使う動詞で、線路自体から降りることは通常表現しない。",
    "correction": "彼は線路から離れた。"
  },
  "word_family_forms": [
    "線路工事",
    "線路脇",
    "線路際"
  ],
  "word_family_fake_forms": [
    {
      "form": "線路性",
      "reason": "「線路性」という抽象名詞は存在しない。"
    },
    {
      "form": "線路化",
      "reason": "「線路化」は一般的な造語法に似ているが、実用されていない。"
    },
    {
      "form": "線路員",
      "reason": "「線路員」は鉄道員の一種のように聞こえるが、正式な職種名ではない。"
    }
  ],
  "syn_ant_candidates": [
    {
      "word": "軌道",
      "type": "synonym",
      "reason": "軌道は線路とほぼ同義で、特に鉄道のレールを指す場合に使われる。"
    },
    {
      "word": "レール",
      "type": "synonym",
      "reason": "レールは線路を構成する部品であるが、しばしば線路そのものを指す比喩として使われる。"
    },
    {
      "word": "道路",
      "type": "antonym",
      "reason": "道路は車両用の通路であり、鉄道の線路とは異なる種類の交通路である。"
    },
    {
      "word": "空路",
      "type": "antonym",
      "reason": "空路は航空機の航路であり、地上の線路とは対照的である。"
    }
  ],
  "particle_candidates": {
    "sentence": "線路___走る電車",
    "blank": "を",
    "correct_particle": "を",
    "candidates": [
      {
        "particle": "を",
        "correct": true,
        "reason": "「走る」は他動詞的に使われ、移動する通路を表す「線路を」が適切。"
      },
      {
        "particle": "が",
        "correct": false,
        "reason": "「線路が」は主格になり、電車が主語と競合する。"
      },
      {
        "particle": "に",
        "correct": false,
        "reason": "「線路に」は到着点や方向を示すが、走る経路としては不自然。"
      },
      {
        "particle": "で",
        "correct": false,
        "reason": "「線路で」は手段・場所を表すが、「走る」の経路としては「を」が標準。"
      }
    ]
  }
}
